import java.util.List;
import java.util.ArrayList;

/**
 * Smooth weighted round robin selects a backend on every call such that,
 * over any window of N calls (N = total weight), each backend is chosen
 * proportional to its weight, while avoiding bursty back-to-back picks
 * of the same high-weight backend, the problem with naive weighted RR.
 */
public class WeightedRoundRobinBalancer {

    private static class Backend {
        final String id;
        final int weight;      // configured, static capacity weight
        int currentWeight;     // mutable running score used for selection

        Backend(String id, int weight) {
            this.id = id;
            this.weight = weight;
            this.currentWeight = 0;
        }
    }

    private final List<Backend> backends;
    private final int totalWeight;

    public WeightedRoundRobinBalancer(List<String> ids, List<Integer> weights) {
        this.backends = new ArrayList<>();
        int sum = 0;
        for (int i = 0; i < ids.size(); i++) {
            backends.add(new Backend(ids.get(i), weights.get(i)));
            sum += weights.get(i);
        }
        this.totalWeight = sum;
    }

    // Every backend's currentWeight is bumped by its static weight each
    // call, the highest currentWeight wins, and the winner's currentWeight
    // is reduced by the total weight so it does not win again until the
    // others have had a fair turn.
    public synchronized String selectBackend() {
        Backend best = null;
        for (Backend b : backends) {
            b.currentWeight += b.weight;
            if (best == null || b.currentWeight > best.currentWeight) {
                best = b;
            }
        }
        best.currentWeight -= totalWeight;
        return best.id;
    }
}

