import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.io.UnsupportedEncodingException;
import java.util.SortedMap;
import java.util.TreeMap;

/**
 * A consistent hash ring for cache-affinity routing. Each real backend is
 * placed at several points on the ring (virtual nodes) so that removing one
 * backend redistributes only its share of keys, roughly total_keys divided
 * by node_count, instead of reshuffling everything the way a plain modulo
 * hash would.
 */
public class ConsistentHashRing {

    private final SortedMap<Long, String> ring = new TreeMap<>();
    private final int virtualNodesPerBackend;

    public ConsistentHashRing(int virtualNodesPerBackend) {
        this.virtualNodesPerBackend = virtualNodesPerBackend;
    }

    public void addBackend(String backendId) {
        for (int i = 0; i < virtualNodesPerBackend; i++) {
            ring.put(hash(backendId + "#" + i), backendId);
        }
    }

    public void removeBackend(String backendId) {
        for (int i = 0; i < virtualNodesPerBackend; i++) {
            ring.remove(hash(backendId + "#" + i));
        }
    }

    // Walks clockwise from the key's hash to the first virtual node point
    // greater than or equal to it, wrapping back to the start of the ring
    // if the key hashes past the last point.
    public String getBackendFor(String key) {
        if (ring.isEmpty()) return null;
        long point = hash(key);
        SortedMap<Long, String> tail = ring.tailMap(point);
        long targetPoint = tail.isEmpty() ? ring.firstKey() : tail.firstKey();
        return ring.get(targetPoint);
    }

    private long hash(String input) {
        try {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] digest = md5.digest(input.getBytes("UTF-8"));
            // Use the first 8 bytes of the digest as a long so points spread
            // evenly across the ring's full numeric range.
            long h = 0;
            for (int i = 0; i < 8; i++) {
                h = (h << 8) | (digest[i] & 0xFF);
            }
            return h;
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }
}

