import hashlib
import bisect


class ConsistentHashRing:
    """Same virtual-node ring as the Java version. bisect on a sorted list of
    points stands in for the TreeMap tailMap lookup."""

    def __init__(self, virtual_nodes_per_backend):
        self.virtual_nodes_per_backend = virtual_nodes_per_backend
        self.ring = {}
        self.sorted_points = []

    def _hash(self, key):
        digest = hashlib.md5(key.encode("utf-8")).digest()
        return int.from_bytes(digest[:8], byteorder="big")

    def add_backend(self, backend_id):
        for i in range(self.virtual_nodes_per_backend):
            point = self._hash(f"{backend_id}#{i}")
            self.ring[point] = backend_id
            bisect.insort(self.sorted_points, point)

    def remove_backend(self, backend_id):
        for i in range(self.virtual_nodes_per_backend):
            point = self._hash(f"{backend_id}#{i}")
            if point in self.ring:
                del self.ring[point]
                self.sorted_points.remove(point)

    def get_backend_for(self, key):
        if not self.sorted_points:
            return None
        point = self._hash(key)
        idx = bisect.bisect_left(self.sorted_points, point)
        if idx == len(self.sorted_points):
            idx = 0  # wrap around to the start of the ring
        return self.ring[self.sorted_points[idx]]

