#include <map>
#include <string>
#include <cstdint>
#include <openssl/md5.h>

class ConsistentHashRing {
public:
    explicit ConsistentHashRing(int virtualNodesPerBackend)
        : virtualNodesPerBackend_(virtualNodesPerBackend) {}

    void addBackend(const std::string& backendId) {
        for (int i = 0; i < virtualNodesPerBackend_; ++i) {
            uint64_t point = hash(backendId + "#" + std::to_string(i));
            ring_[point] = backendId;
        }
    }

    void removeBackend(const std::string& backendId) {
        for (int i = 0; i < virtualNodesPerBackend_; ++i) {
            ring_.erase(hash(backendId + "#" + std::to_string(i)));
        }
    }

    // std::map keeps keys sorted, so lower_bound gives the same "next point
    // clockwise" lookup as the Java TreeMap tailMap and the Python bisect version.
    std::string getBackendFor(const std::string& key) {
        if (ring_.empty()) return "";
        uint64_t point = hash(key);
        auto it = ring_.lower_bound(point);
        if (it == ring_.end()) it = ring_.begin();
        return it->second;
    }

private:
    uint64_t hash(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5(reinterpret_cast<const unsigned char*>(input.c_str()), input.size(), digest);
        uint64_t h = 0;
        for (int i = 0; i < 8; ++i) {
            h = (h << 8) | digest[i];
        }
        return h;
    }

    std::map<uint64_t, std::string> ring_;
    int virtualNodesPerBackend_;
};

