import threading


class BackendPool:
    """Same registry as the Java version: the single source of truth every
    routing algorithm reads the current healthy list from."""

    def __init__(self):
        self._lock = threading.Lock()
        self._weights = {}
        self._healthy = {}

    def register(self, backend_id, weight):
        with self._lock:
            self._weights[backend_id] = weight
            self._healthy[backend_id] = True  # assume healthy until the first probe

    def deregister(self, backend_id):
        with self._lock:
            self._weights.pop(backend_id, None)
            self._healthy.pop(backend_id, None)

    def mark_healthy(self, backend_id):
        with self._lock:
            if backend_id in self._weights:
                self._healthy[backend_id] = True

    def mark_unhealthy(self, backend_id):
        with self._lock:
            if backend_id in self._weights:
                self._healthy[backend_id] = False

    def all_backend_ids(self):
        with self._lock:
            return list(self._weights.keys())

    def healthy_backend_ids(self):
        with self._lock:
            return [b for b, healthy in self._healthy.items() if healthy]

    def weight_of(self, backend_id):
        with self._lock:
            return self._weights.get(backend_id, 0)

