        if (weights_.count(backendId)) healthy_[backendId] = false;
    }

    std::vector<std::string> allBackendIds() {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<std::string> ids;
        for (const auto& entry : weights_) ids.push_back(entry.first);
        return ids;
    }

    // The only list the routing algorithms are allowed to pick from.
    std::vector<std::string> healthyBackendIds() {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<std::string> ids;
        for (const auto& entry : healthy_) {
            if (entry.second) ids.push_back(entry.first);
        }
        return ids;
    }

    int weightOf(const std::string& backendId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = weights_.find(backendId);
        return it == weights_.end() ? 0 : it->second;
    }

