import java.util.*;
import java.util.concurrent.*;

/**
 * The registry of every backend behind this load balancer, and the single
 * source of truth every routing algorithm reads from. Health state changes
 * here are what actually pull a backend out of rotation; the algorithms
 * themselves only ever see the currently-healthy list.
 */
public class BackendPool {

    private final ConcurrentHashMap<String, Boolean> healthStatus = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Integer> weights = new ConcurrentHashMap<>();

    public void register(String backendId, int weight) {
        weights.put(backendId, weight);
        healthStatus.put(backendId, true); // assume healthy until the first probe says otherwise
    }

    public void deregister(String backendId) {
        weights.remove(backendId);
        healthStatus.remove(backendId);
    }

    public void markHealthy(String backendId) {
        if (weights.containsKey(backendId)) healthStatus.put(backendId, true);
    }

    public void markUnhealthy(String backendId) {
        if (weights.containsKey(backendId)) healthStatus.put(backendId, false);
    }

    public List<String> allBackendIds() {
        return new ArrayList<>(weights.keySet());
    }

    // The only list the routing algorithms are allowed to pick from.
    public List<String> healthyBackendIds() {
        List<String> healthy = new ArrayList<>();
        for (Map.Entry<String, Boolean> entry : healthStatus.entrySet()) {
            if (Boolean.TRUE.equals(entry.getValue())) healthy.add(entry.getKey());
        }
        return healthy;
    }

    public int weightOf(String backendId) {
        return weights.getOrDefault(backendId, 0);
    }
}

