import java.util.concurrent.*;
import java.util.function.Predicate;

/**
 * Active health checking: probes every registered backend on a fixed
 * interval and only flips its status after a run of consecutive results,
 * which is what keeps a single flaky probe from flapping a backend in and
 * out of rotation.
 */
public class HealthChecker {

    private final BackendPool pool;
    private final Predicate<String> probe;  // true if the backend responded healthy
    private final int unhealthyThreshold;   // consecutive failures before pulling a backend
    private final int healthyThreshold;     // consecutive successes before restoring it
    private final ConcurrentHashMap<String, Integer> consecutiveFailures = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Integer> consecutiveSuccesses = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(4);

    public HealthChecker(BackendPool pool, Predicate<String> probe,
                          int unhealthyThreshold, int healthyThreshold) {
        this.pool = pool;
        this.probe = probe;
        this.unhealthyThreshold = unhealthyThreshold;
        this.healthyThreshold = healthyThreshold;
    }

    public void start(long intervalMillis) {
        scheduler.scheduleAtFixedRate(this::probeAll, 0, intervalMillis, TimeUnit.MILLISECONDS);
    }

    private void probeAll() {
        for (String backendId : pool.allBackendIds()) {
            recordResult(backendId, safeProbe(backendId));
        }
    }

    // Wraps the actual probe call so a thrown exception (connection refused,
    // timeout) is treated as a failed check rather than crashing the checker.
    private boolean safeProbe(String backendId) {
        try {
            return probe.test(backendId);
        } catch (Exception e) {
            return false;
        }
    }

    private void recordResult(String backendId, boolean healthy) {
        if (healthy) {
            consecutiveFailures.put(backendId, 0);
            int successes = consecutiveSuccesses.merge(backendId, 1, Integer::sum);
            if (successes >= healthyThreshold) pool.markHealthy(backendId);
        } else {
            consecutiveSuccesses.put(backendId, 0);
            int failures = consecutiveFailures.merge(backendId, 1, Integer::sum);
            if (failures >= unhealthyThreshold) pool.markUnhealthy(backendId);
        }
    }

    public void stop() {
        scheduler.shutdownNow();
    }
}

