import threading


class HealthChecker:
    """Same consecutive-threshold active probing as the Java version, using
    a background thread instead of a scheduled executor service."""

    def __init__(self, pool, probe_fn, unhealthy_threshold, healthy_threshold):
        self.pool = pool
        self.probe_fn = probe_fn
        self.unhealthy_threshold = unhealthy_threshold
        self.healthy_threshold = healthy_threshold
        self.consecutive_failures = {}
        self.consecutive_successes = {}
        self._stop_event = threading.Event()
        self._thread = None

    def start(self, interval_seconds):
        def loop():
            while not self._stop_event.is_set():
                self._probe_all()
                self._stop_event.wait(interval_seconds)
        self._thread = threading.Thread(target=loop, daemon=True)
        self._thread.start()

    def _probe_all(self):
        for backend_id in self.pool.all_backend_ids():
            self._record_result(backend_id, self._safe_probe(backend_id))

    def _safe_probe(self, backend_id):
        # A timeout or connection error counts as a failed check, exactly
        # like the Java version's try/catch around the probe call.
        try:
            return self.probe_fn(backend_id)
        except Exception:
            return False

    def _record_result(self, backend_id, healthy):
        if healthy:
            self.consecutive_failures[backend_id] = 0
            successes = self.consecutive_successes.get(backend_id, 0) + 1
            self.consecutive_successes[backend_id] = successes
            if successes >= self.healthy_threshold:
                self.pool.mark_healthy(backend_id)
        else:
            self.consecutive_successes[backend_id] = 0
            failures = self.consecutive_failures.get(backend_id, 0) + 1
            self.consecutive_failures[backend_id] = failures
            if failures >= self.unhealthy_threshold:
                self.pool.mark_unhealthy(backend_id)

    def stop(self):
        self._stop_event.set()

