#include <mutex>
#include <string>

class HealthChecker {
public:
    using ProbeFn = std::function<bool(const std::string&)>;

    HealthChecker(BackendPool& pool, ProbeFn probe,
                   int unhealthyThreshold, int healthyThreshold)
        : pool_(pool), probe_(std::move(probe)),
          unhealthyThreshold_(unhealthyThreshold),
          healthyThreshold_(healthyThreshold), running_(false) {}

    void start(int intervalMs) {
        running_ = true;
        worker_ = std::thread([this, intervalMs]() {
            while (running_) {
                probeAll();
                std::this_thread::sleep_for(std::chrono::milliseconds(intervalMs));
            }
        });
    }

    void stop() {
        running_ = false;
        if (worker_.joinable()) worker_.join();
    }

private:
    void probeAll() {
        for (const auto& backendId : pool_.allBackendIds()) {
            recordResult(backendId, safeProbe(backendId));
        }
    }

    // A thrown exception from the probe function counts as a failure, same
    // fail-safe behavior as the Java and Python versions.
    bool safeProbe(const std::string& backendId) {
        try {
            return probe_(backendId);
        } catch (...) {
            return false;
        }
    }

    void recordResult(const std::string& backendId, bool healthy) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (healthy) {
            failures_[backendId] = 0;
            int successes = ++successes_[backendId];
            if (successes >= healthyThreshold_) pool_.markHealthy(backendId);
        } else {
            successes_[backendId] = 0;
            int failures = ++failures_[backendId];
            if (failures >= unhealthyThreshold_) pool_.markUnhealthy(backendId);
        }
    }

    BackendPool& pool_;
    ProbeFn probe_;
    int unhealthyThreshold_;
    int healthyThreshold_;
    std::atomic<bool> running_;
    std::thread worker_;
    std::unordered_map<std::string, int> failures_;
    std::unordered_map<std::string, int> successes_;
    std::mutex mutex_;
};

