import java.util.concurrent.*;

/**
 * Maps a client's session identifier (typically a cookie value) to the
 * backend it was first routed to, so subsequent requests in the same
 * session keep landing on the same instance. Entries expire on their own
 * so a client that never comes back does not leak memory forever.
 */
public class StickySessionManager {

    private static class Entry {
        final String backendId;
        final long expiresAtMillis;

        Entry(String backendId, long expiresAtMillis) {
            this.backendId = backendId;
            this.expiresAtMillis = expiresAtMillis;
        }
    }

    private final ConcurrentHashMap<String, Entry> sessions = new ConcurrentHashMap<>();
    private final long ttlMillis;

    public StickySessionManager(long ttlMillis) {
        this.ttlMillis = ttlMillis;
    }

    // Called once, the first time a session is seen, to pin it to whichever
    // backend the normal load-balancing algorithm just picked.
    public void bind(String sessionId, String backendId) {
        sessions.put(sessionId, new Entry(backendId, System.currentTimeMillis() + ttlMillis));
    }

    // Returns the pinned backend if the session is known and not expired, or
    // null if the caller should fall through to the normal algorithm, which
    // covers both a brand new session and one whose TTL lapsed.
    public String getPinnedBackend(String sessionId) {
        Entry entry = sessions.get(sessionId);
        if (entry == null) return null;
        if (System.currentTimeMillis() > entry.expiresAtMillis) {
            sessions.remove(sessionId);
            return null;
        }
        return entry.backendId;
    }

    // Called by the health checker when a backend is marked unhealthy, so
    // every session pinned to it gets released back to the normal algorithm
    // instead of staying stuck retrying a dead instance.
    public void releaseAllFor(String backendId) {
        sessions.entrySet().removeIf(e -> e.getValue().backendId.equals(backendId));
    }
}

