import time
import threading


class StickySessionManager:
    """Cookie-based session affinity, same TTL and release-on-failure
    behavior as the Java version."""

    def __init__(self, ttl_seconds):
        self.ttl_seconds = ttl_seconds
        self._sessions = {}
        self._lock = threading.Lock()

    def bind(self, session_id, backend_id):
        with self._lock:
            self._sessions[session_id] = (backend_id, time.time() + self.ttl_seconds)

    def get_pinned_backend(self, session_id):
        with self._lock:
            entry = self._sessions.get(session_id)
            if entry is None:
                return None
            backend_id, expires_at = entry
            if time.time() > expires_at:
                del self._sessions[session_id]
                return None
            return backend_id

    def release_all_for(self, backend_id):
        with self._lock:
            expired = [sid for sid, (bid, _) in self._sessions.items() if bid == backend_id]
            for sid in expired:
                del self._sessions[sid]

