#include <string>
#include <unordered_map>
#include <chrono>
#include <mutex>

class StickySessionManager {
public:
    explicit StickySessionManager(long ttlSeconds) : ttlSeconds_(ttlSeconds) {}

    void bind(const std::string& sessionId, const std::string& backendId) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_[sessionId] = {backendId, now() + ttlSeconds_};
    }

    // Returns an empty string if the session is unknown or expired, telling
    // the caller to fall through to the normal load-balancing algorithm.
    std::string getPinnedBackend(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = sessions_.find(sessionId);
        if (it == sessions_.end()) return "";
        if (now() > it->second.expiresAt) {
            sessions_.erase(it);
            return "";
        }
        return it->second.backendId;
    }

    void releaseAllFor(const std::string& backendId) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end();) {
            if (it->second.backendId == backendId) {
                it = sessions_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    struct Entry {
        std::string backendId;
        long expiresAt;
    };

    long now() {
        return std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }

    long ttlSeconds_;
    std::unordered_map<std::string, Entry> sessions_;
    std::mutex mutex_;
};

